//! Runtime behavior of tools generated by `#[openjiuwen_macros::tool]`.
//!
//! Every tool here is declared exactly as a user crate would declare it, and
//! exercised only through the generated API (`NAME`/`DESCRIPTION`, `new()`,
//! `{fn}_tool()`, `impl Tool`), so the tests pin the macro contract rather than
//! the implementation.
#![allow(clippy::unwrap_used, clippy::expect_used)]
// `#[tool]` requires `async fn`, so these thin wrappers have nothing to await.
#![allow(clippy::unused_async)]

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use openjiuwen_common::error::{Error, ErrorKind, Result};
use openjiuwen_foundation::tool::{Tool, ToolContext, ToolExecution, ToolExposure, ToolOutput};
use openjiuwen_macros::tool;
use schemars::JsonSchema;
use serde::Deserialize;
use serde_json::{json, Value};

/// Shared argument struct for the tools that only need one integer.
#[derive(Debug, Deserialize, JsonSchema)]
struct PingArgs {
    value: i64,
}

#[derive(Debug, Deserialize, JsonSchema)]
struct AddArgs {
    a: i64,
    b: i64,
}

#[derive(Debug, Deserialize, JsonSchema)]
struct EchoArgs {
    text: String,
}

/// Deserializes but deliberately does not implement `JsonSchema`, proving that
/// `input_params` removes the schema bound.
#[derive(Debug, Deserialize)]
struct RawArgs {
    x: String,
}

/// Add two integers.
#[tool(name = "add")]
async fn add(args: AddArgs) -> Result<i64> {
    Ok(args.a + args.b)
}

#[tool(name = "sum_values")]
async fn add_values(args: AddArgs) -> Result<i64> {
    Ok(args.a + args.b)
}

/// Ping.
#[tool]
async fn ping(args: PingArgs) -> Result<String> {
    Ok(args.value.to_string())
}

/// Echo text.
///
/// Args:
///     text: the text to echo
#[tool(name = "echo_text", description = "Echo the given text.")]
async fn echo(args: EchoArgs) -> Result<String> {
    Ok(args.text)
}

#[tool]
async fn get_url(args: PingArgs) -> Result<String> {
    Ok(args.value.to_string())
}

#[tool]
async fn read_write_tool(args: PingArgs) -> Result<Value> {
    Ok(json!(args.value))
}

#[tool]
async fn session_echo(args: PingArgs, ctx: &ToolContext) -> Value {
    json!({ "value": args.value, "session": ctx.session_id })
}

#[tool]
async fn report(args: PingArgs, ctx: ToolContext) -> Value {
    json!({ "value": args.value, "invocation": ctx.invocation_id })
}

#[tool]
async fn double(args: PingArgs) -> i64 {
    args.value * 2
}

#[tool]
async fn nothing(_args: PingArgs) {}

#[tool]
async fn failing(args: PingArgs) -> Result<Value> {
    Err(Error::tool(format!("boom {}", args.value)))
}

#[tool]
async fn structured(args: PingArgs) -> Result<ToolOutput> {
    Ok(ToolOutput::success(
        json!({ "content": args.value.to_string() }),
    ))
}

#[tool(name = "crate_visible")]
pub(crate) async fn crate_visible(args: PingArgs) -> Result<i64> {
    Ok(args.value)
}

/// Policy keys all supplied, so every `.with_*` branch is exercised.
#[tool(
    name = "policy",
    description = "Policy e2e",
    stateless = true,
    parallel_safe = false,
    idempotent = true,
    exposure = "deferred",
    execution = "client"
)]
async fn policy(args: PingArgs) -> Result<String> {
    Ok(format!("policy {}", args.value))
}

/// Raw schema supplied by the caller; `RawArgs` has no `JsonSchema` derive.
#[tool(
    name = "raw",
    input_params = serde_json::json!({
        "type": "object",
        "properties": { "x": { "type": "string" } },
        "required": ["x"]
    })
)]
async fn raw(args: RawArgs) -> Result<String> {
    Ok(args.x)
}

static CANCELLED_CALLS: AtomicUsize = AtomicUsize::new(0);

#[tool]
async fn counted(args: PingArgs) -> Result<Value> {
    CANCELLED_CALLS.fetch_add(1, Ordering::SeqCst);
    Ok(json!(args.value))
}

#[tokio::test]
async fn unary_tool_invokes_the_function() {
    let output = AddTool::new()
        .invoke(json!({ "a": 2, "b": 3 }), &ToolContext::new())
        .await
        .unwrap();
    assert_eq!(output, json!(5));
}

#[tokio::test]
async fn constructor_returns_an_arc_dyn_tool() {
    let tool: Arc<dyn Tool> = add_tool();
    assert_eq!(tool.card().name, "add");
    let output = tool
        .invoke(json!({ "a": 1, "b": 4 }), &ToolContext::new())
        .await
        .unwrap();
    assert_eq!(output, json!(5));
}

#[tokio::test]
async fn original_function_remains_callable() {
    assert_eq!(add(AddArgs { a: 1, b: 2 }).await.unwrap(), 3);
}

#[tokio::test]
async fn borrowed_context_receives_the_session() {
    let context = ToolContext::new().with_session("session-1");
    let output = session_echo_tool()
        .invoke(json!({ "value": 7 }), &context)
        .await
        .unwrap();
    assert_eq!(output["value"], 7);
    assert_eq!(output["session"], "session-1");
}

#[tokio::test]
async fn owned_context_is_moved_into_the_function() {
    let output = report_tool()
        .invoke(json!({ "value": 3 }), &ToolContext::new())
        .await
        .unwrap();
    assert_eq!(output["value"], 3);
    let invocation = output["invocation"].as_str().unwrap();
    assert_eq!(invocation.len(), 32);
    assert!(invocation
        .chars()
        .all(|character| character.is_ascii_hexdigit()));
}

#[tokio::test]
async fn card_reports_name_and_description() {
    let tool = AddTool::new();
    assert_eq!(tool.card().name, "add");
    assert_eq!(tool.card().description, "Add two integers.");
}

#[tokio::test]
async fn name_attribute_only_renames_the_card() {
    let tool = AddValuesTool::new();
    assert_eq!(tool.card().name, "sum_values");
    // No doc comment: the humanized function name is used.
    assert_eq!(tool.card().description, "add values");
}

#[tokio::test]
async fn card_input_params_comes_from_schemars() {
    let card = AddTool::new().card().clone();
    assert_eq!(card.input_params["type"], "object");
    let properties = card.input_params["properties"].as_object().unwrap();
    assert!(properties.contains_key("a"));
    assert!(properties.contains_key("b"));
    let required: Vec<&str> = card.input_params["required"]
        .as_array()
        .unwrap()
        .iter()
        .map(|value| value.as_str().unwrap())
        .collect();
    assert!(required.contains(&"a"));
    assert!(required.contains(&"b"));
    assert!(card.input_params.get("$schema").is_none());
}

#[test]
fn name_and_description_constants_are_exposed() {
    assert_eq!(AddTool::NAME, "add");
    assert_eq!(AddTool::DESCRIPTION, "Add two integers.");
    assert_eq!(EchoTool::NAME, "echo_text");
    assert_eq!(EchoTool::DESCRIPTION, "Echo the given text.");
}

#[test]
fn description_comes_from_the_first_doc_paragraph() {
    assert_eq!(PingTool::DESCRIPTION, "Ping.");
}

#[test]
fn description_stops_at_a_blank_line_and_section_marker() {
    let card = EchoTool::new().card().clone();
    assert_eq!(card.description, "Echo the given text.");
}

#[test]
fn description_falls_back_to_the_humanized_name() {
    assert_eq!(GetUrlTool::DESCRIPTION, "get URL");
}

#[test]
fn humanized_names_lowercase_words() {
    assert_eq!(ReadWriteToolTool::DESCRIPTION, "read write tool");
}

#[test]
fn policy_keys_reach_the_card() {
    let card = PolicyTool::new().card().clone();
    assert_eq!(card.name, "policy");
    assert_eq!(card.description, "Policy e2e");
    assert!(card.stateless);
    assert!(!card.parallel_safe);
    assert!(card.idempotent);
    assert_eq!(card.exposure, ToolExposure::Deferred);
    assert_eq!(card.execution, ToolExecution::Client);
}

#[test]
fn default_policy_matches_the_python_defaults() {
    let card = PingTool::new().card().clone();
    assert!(!card.stateless);
    assert!(card.parallel_safe);
    assert!(!card.idempotent);
    assert_eq!(card.exposure, ToolExposure::Direct);
    assert_eq!(card.execution, ToolExecution::Server);
}

#[tokio::test]
async fn input_params_override_skips_the_json_schema_bound() {
    assert_eq!(
        RawTool::new().card().input_params["properties"]["x"]["type"],
        "string"
    );
    let output = RawTool::new()
        .invoke(json!({ "x": "hello" }), &ToolContext::new())
        .await
        .unwrap();
    assert_eq!(output, json!("hello"));
}

#[tokio::test]
async fn plain_return_type_is_serialized() {
    let output = DoubleTool::new()
        .invoke(json!({ "value": 21 }), &ToolContext::new())
        .await
        .unwrap();
    assert_eq!(output, json!(42));
}

#[tokio::test]
async fn unit_return_serializes_to_null() {
    let output = NothingTool::new()
        .invoke(json!({ "value": 1 }), &ToolContext::new())
        .await
        .unwrap();
    assert_eq!(output, Value::Null);
}

#[tokio::test]
async fn handler_error_is_propagated_unchanged() {
    let error = FailingTool::new()
        .invoke(json!({ "value": 7 }), &ToolContext::new())
        .await
        .unwrap_err();
    assert!(matches!(&error, Error::Tool(message) if message == "boom 7"));
}

#[tokio::test]
async fn invalid_input_is_a_validation_error() {
    let error = AddTool::new()
        .invoke(json!({ "a": 1 }), &ToolContext::new())
        .await
        .unwrap_err();
    assert_eq!(error.kind(), ErrorKind::Validation);
}

#[tokio::test]
async fn cancelled_context_short_circuits_before_the_handler() {
    let context = ToolContext::new();
    context.cancellation.cancel();
    let error = counted_tool()
        .invoke(json!({ "value": 1 }), &context)
        .await
        .unwrap_err();
    assert!(matches!(error, Error::Cancelled));
    assert_eq!(CANCELLED_CALLS.load(Ordering::SeqCst), 0);
}

#[test]
fn default_impl_builds_a_tool() {
    let tool = AddTool::default();
    assert_eq!(tool.card().name, "add");
}

#[test]
fn card_ids_are_fresh_per_tool() {
    assert_ne!(AddTool::new().card().id, AddTool::new().card().id);
}

#[test]
fn generated_tool_can_be_boxed_as_dyn_tool() {
    let tool: Box<dyn Tool> = Box::new(CrateVisibleTool::new());
    assert_eq!(tool.card().name, "crate_visible");
    assert_eq!(crate_visible_tool().card().name, "crate_visible");
}

#[tokio::test]
async fn stream_yields_exactly_one_item() {
    use futures::StreamExt;

    let tool: Arc<dyn Tool> = ping_tool();
    let mut stream = tool.stream(json!({ "value": 9 }), ToolContext::new());
    let first = stream.next().await.expect("one item").expect("success");
    assert_eq!(first, json!("9"));
    assert!(stream.next().await.is_none());
}

#[test]
fn render_for_llm_uses_the_tool_output_rules() {
    let tool = ping_tool();
    let success = serde_json::to_value(ToolOutput::success(json!({ "content": "ok" }))).unwrap();
    assert_eq!(tool.render_for_llm(&success), "ok");
    let payload = json!({ "content": "hi" });
    assert_eq!(tool.render_for_llm(&payload), "hi");
}

#[test]
fn is_parallel_safe_reflects_the_card() {
    assert!(PingTool::new().is_parallel_safe());
    assert!(!PolicyTool::new().is_parallel_safe());
}

#[tokio::test]
async fn structured_output_round_trips_through_json() {
    let output = StructuredTool::new()
        .invoke(json!({ "value": 7 }), &ToolContext::new())
        .await
        .unwrap();
    assert!(output["success"].as_bool().unwrap());
    assert_eq!(output["data"]["content"], "7");
    let rendered = StructuredTool::new().render_for_llm(&output);
    assert_eq!(rendered, "7");
}
